"Das Bild konnte nicht gelesen werden.":"无法读取该图像。",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"图像作为底图放在平面上。之后可在属性窗口中设置大小、位置、旋转和不透明度（例如按已知尺寸设置宽度）。",
"Das Ergebnis des Geometriekerns ist unlesbar":"几何内核的结果无法读取",
"Das Ergebnis konnte nicht geschrieben werden":"无法写入结果",
"Das Maß muss größer als 0 sein.":"尺寸必须大于 0。",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"网格仍为三角网格(非 B-Rep)。可在“网格”选项卡中编辑：修复、简化、平滑、平面切割 … “制造”中的 3D 铣削策略可直接对其加工。",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"轮廓不得与轴线相交。草图中的开放直线可用作轴线。",
"Das Profil mit den jetzigen Werten überschreiben":"用当前值覆盖此配置",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"轮廓沿一条直线/折线扫掠。轮廓最好垂直于路径起点绘制（例如轮廓在 XZ，路径在 XY）。",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"轮廓从草图平面起凸起或凹陷压印。",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"毛坯为包围所选实体的长方体(加偏移)。",
"Das Setup hat keine Operationen.":"该设置没有工序。",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"刀具沿圆周铣削，圆心沿槽移动。刀具始终不会全宽切入 – 因此可采用较大的每层切深，并保护铣刀和主轴。铣刀直径应约为槽宽的 60 %。",
"Das Werkzeug schneidet die Fläche nicht":"修剪工具与曲面不相交",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"刀具朝所选面切削，直至达到指定余量。",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"刀具像钻头一样逐行垂直插入，直到模型加余量为止。切削力沿主轴方向作用：适用于长刀具、深型腔和刚性较差的机床。刀具必须能过中心切削。{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"刀具按指定的安全距离避让这些面(压板、虎钳)。",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"刀具在加工邻近面时避让这些面，并保持安全距离。",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"第一次 Esc 只取消工具或选择——多按一次 Esc 也不会关闭草图",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"这不是孔（是圆角或凸台）– 请单击孔的内壁。",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"这不是孔（圆柱面）– 请单击孔壁。",
"Das ist keine WerkFab-Design-Datei.":"这不是 WerkFab 主题文件。",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"这不是斜边 – 请单击倒角边的两个端点。",
