"Deckkraft der Fenster":"窗口不透明度",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"直径将变为零或负值 – 请减小距离",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"螺纹铣刀在整块材料中切削：请先把凸台周围铣开（围绕凸台的外侧 2D 轮廓，铣到螺纹深度）。",
"Der Körper hat auf dieser Ebene keinen Umriss.":"该实体在此平面上没有轮廓。",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"将绕实体的竖直中心轴采样，并作为刀夹轮廓(分段)保存到文档刀具库中。",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"视图旋转所围绕的点（自由动态观察时）。“指针下方”：开始旋转时指针所在的模型位置。",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"半径沿每条所选边从起点到终点均匀增大。哪一端为起点由边决定 – 必要时交换。",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"面的边界是一条闭合链：启用“连续”时，半径沿整圈变化一次；不启用时，每条边各自从起始半径变化到终止半径。",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"切除未碰到任何实体——不会去除材料。",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"该文本作为注释写在程序的此位置。",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"第一个距离在更朝上(Z)的面上测量，第二个距离或角度则针对另一个面。“交换两侧”可将其对调。相切连接的边会一并处理。",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"所选实体即为毛坯(例如铸件或锻件毛坯)。其本身不被加工。",
"Der große Geometriekern ist noch nicht geladen":"完整几何内核尚未加载",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"正在加载完整几何内核 – 此步骤稍后将自动重新计算",
