"Design nicht gefunden.":"未找到设计。",
"Design, Farben, Symbole, Form und Schrift in einer Datei – zum Weitergeben oder für einen anderen Rechner":"将主题、颜色、图标、形状和字体保存在一个文件中——便于分享或用于另一台电脑",
