"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"自己添加的尺寸和注释可在图纸上用鼠标拖动(尺寸线的距离、指引线的角度、角度圆弧的半径)。单击两个角点 = 长度尺寸。在俯视图中单击圆的边缘 = 直径(或半径)。角度：先单击顶点，再在两条边上各单击一个角点。倒角：单击斜边的两端——得到例如 2×45°。每个尺寸后面的文本框中可填写附加内容，如 ±0,1、H7 或 4×。",
