"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"先单击要移动的实体上的面，再单击另一实体上的目标面。实体将旋转并移动，直到第一个单击点与第二个重合且两个面相互贴合。",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"先单击要移动的实体上的边，再单击另一实体上的目标边。直边相互重合(中点对中点)；对于圆形边 – 孔与销 – 则使轴线方向一致并使圆心重合。",
