"Flächen (aufeinander legen)":"面(相互贴合)",
"Flächen am Körper":"实体上的面",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"用动力平底立铣刀沿 Z 在零件端部加工平面(双扁、四方、六方)。对边宽度 = 平面到旋转轴距离的两倍。X 和 C 联动(极坐标插补，Fanuc G12.1)；后处理器中没有该模板时，输出短的 X/C 步进。",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"单击要加厚的面(再次单击取消选择)。",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"单击要拔模的面(再次单击取消选择)。",
"Flächen anklicken, die offen sein sollen.":"单击需要开口的面。",
