"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Fusion 360 文件 (.f3d) 是 Autodesk 的封闭格式，无法读取。\n\n在 Fusion 360 中：选择 文件 → 导出 → STEP (.stp)，然后在此处导入该文件。",
