"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"在设置的“毛坯 → 毛坯材料”下选择材料。密度用于计算毛坯重量，Vc 为硬质合金的参考值；颜色在仿真中显示。",
