"Materialien über „Darstellung“ (A) auf die Körper ziehen. Beim In-Canvas-Rendern wird das Bild mit jedem Durchgang glatter (weiche Schatten, saubere Kanten); jede Kamerabewegung beginnt neu.":"通过“外观”(A) 将材料拖到实体上。画布内渲染时，图像随每次迭代变得更平滑（柔和阴影、干净边缘）；每次移动相机都会重新开始。",
