"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"多条相连的边视为一段路径：半径从链的起点延续到终点，控制点按整条链长度的 % 计算。由完整几何内核计算。",
