"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"使用控制点时，半径按给定的数值变化（位置为边长的百分比）。此计算由完整几何内核完成；首次使用时需加载几秒钟。",
"Mit dem 3D-Taster kann nicht zerspant werden":"3D 测头不能用于切削",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"与成品零件比较：绿色 = 尺寸到位，蓝色 = 残料，红色 = 过深",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"将鼠标移到轮廓旁(所在一侧决定方向) · Esc 结束",
"Mit diesem Werkzeug kann nicht gefräst werden":"此刀具不能用于铣削",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"丝锥只能使用“攻丝”循环 – 钻孔循环会将其折断",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"采用多次进刀时，螺纹深度分步铣削，每步的切除量大致相同 – 有利于保护小直径螺纹铣刀和加工硬材料。光刀是在不再进刀的情况下把最后一条刀路重走一遍。",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"在NC程序中启用“钻孔循环”时输出系统固定循环(G81–G86，Heidenhain CYCL 200–207，Sinumerik CYCLE81–85)，否则输出展开的运动。",
