"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"只有矩形和圆形型腔可用系统固定循环",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"仅加工较大铣刀在拐角处留下的材料。",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"仅重走较大铣刀未能到达的轮廓部位(内角、狭窄处)。不含切入/切出圆弧、连接桥和精加工走刀；在计算机中补偿。",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"仅加工参考刀具未能到达的区域：平缓区域用平行加工，陡峭区域用等高线加工。选用列表中的刀具时，其形状也计算在内 – 例如圆鼻铣刀在内圆角处留下的残料。",
