"Nut liegt nicht am Teil":"槽不在零件上",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"用指向轴线的动力铣刀沿旋转轴方向加工槽(例如键槽)；主轴作为 C 轴固定零件。槽宽 = 铣刀Ø。起点/终点 Z 按模型 Z；若槽延伸到端面，铣刀从前方切入，否则在起点直插下刀。深度自外径起算。",
