"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"开放或闭合曲线垂直于草图拉伸 – 生成曲面（无厚度的壁）。使用“加厚”或“缝合”可将其变为实体。",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"开放或闭合曲线绕轴旋转 – 生成的是曲面，而不是实体。",
"Ohne eigene Taste gilt der Standard „{0}“.":"未自定义按键时使用默认的“{0}”。",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"不勾选“建模”时螺纹仅作显示（速度快）。勾选后会真正切出螺纹牙形，例如用于 3D 打印。M8 的底孔 = Ø6,8。",
"Okuma OSP Drehen":"Okuma OSP 车削",
"Okuma OSP-M Fräsen":"Okuma OSP-M 铣削",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP：G28/G53 在该系统上不移动到机床坐标(G53 会取消刀具长度补偿) – 退刀至安全高度，不输出 XY 回零",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP：未输出平滑功能(G5.1 属于 Fanuc) – 请在机床上设置 Hi-Cut/Super-NURBS",
