"Schruppt die Bohrung von der Vorbohrung nach außen (0,2 mm Schlichtaufmaß) und schlichtet sie dann bis zum Grund. Die Bohrstange muss in die Vorbohrung passen.":"从预钻孔向外粗加工内孔(精加工余量 0,2 mm)，然后精加工至孔底。镗刀杆必须能进入预钻孔。",
"Schruppt simultan 4-achsig von außen nach innen: je Zustellung eine Spirale um die A-Achse (abwechselnd in +X und −X), nie tiefer als das Teil plus Aufmaß. Mit Schaft- oder Kugelfräser.":"四轴联动由外向内粗加工：每层切深绕 A 轴走一条螺旋线(在 +X 和 −X 方向交替)，深度不超过零件加余量。使用平底立铣刀或球头铣刀。",
